+(settings.logo ? '<div class="logo-card">'+logoHtml+'</div>' : '')
+'<div class="co-meta">'
+(!settings.logo ? '<b style="font-size:13px">'+co+'</b><br>' : '')
+headerInfo
+'</div></div>'
+'<div class="doc-right">'
