async function openDeliveryConfirmationFromDNView(){
  const viewModal=document.getElementById('dn-print-modal');const soId=viewModal?._soId,deliveryIdx=viewModal?._deliveryIdx;if(soId==null||deliveryIdx==null){showToast('Unable to identify this Delivery Note','error');return}
  const so=salesOrders.find(x=>x.id===soId),d=so?.deliveries?.[deliveryIdx];
  if(d?.voided){showToast('This Delivery Note has been voided.','warning');return;}
  if(d?.customerConfirmed){
    const panel=document.querySelector('#dn-print-body .dn-confirm-result');
    const toggle=panel?.querySelector('.dn-confirm-toggle');
    if(toggle&&toggle.getAttribute('aria-expanded')!=='true')toggle.click();
    panel?.scrollIntoView({behavior:'smooth',block:'start'});
    return;
  }
  // V265.3: openDeliveryAcceptance is wrapped by the document lock (async) — wait for it before checking the screen.
  try{const opened=await openDeliveryAcceptance(soId,deliveryIdx),confirmModal=document.getElementById('dn-confirm-modal');if(opened===false&&!confirmModal?.classList.contains('open'))return;if(confirmModal?.classList.contains('open')){viewModal?.classList.remove('open','modal-fs-overlay');updateFullscreenShellState();confirmModal.style.zIndex='6200';return}showToast('Could not open Delivery Confirmation','error')}catch(err){console.error('Delivery Confirmation open failed',err);showToast('Could not open Delivery Confirmation: '+(err?.message||'Unknown error'),'error')}
}
/** V270.4.8: customer PO number for a PDF file name — "PO2200005124" ('' when there is none; an existing "PO" prefix is not doubled). */
function docPoFilePart(po){
  const t=String(po||'').trim().replace(/^p\.?\s*o\.?\s*(no\.?|number|#)?\s*[:\-#]?\s*/i,'');
  return t?dnSafeFilePart('PO'+t):'';
}
function dnSafeFilePart(value){
  return String(value||'').replace(/[\\/:*?"<>|]+/g,' ').replace(/\s+/g,' ').trim().replace(/[. ]+$/,'');
}
function printDeliveryNote(format='standard',soArg=null,dArg=null,idxArg=null) {
  const vm=document.getElementById('dn-print-modal');
  const so=soArg||salesOrders.find(x=>x.id===vm?._soId);
  const idx=(idxArg!==null&&idxArg!==undefined)?idxArg:vm?._deliveryIdx;
  const d=dArg||so?.deliveries?.[idx];if(!so||!d)return;if(d.voided){showToast('Voided Delivery Notes cannot be printed as active dispatches.','warning');return;}
  if(d.voided){showToast('Voided Delivery Notes cannot be printed.','warning');return;}
  if((format==='accepted-standard'||format==='accepted-progress')&&(!d.customerConfirmed||!(d.items||[]).some(it=>deliveryAcceptedQty(d,it)>0))){showToast('No confirmed accepted quantities available to print','warning');return;}
  let html=buildDeliveryNoteDocument(so,d,idx,format,false);
  const qrCanvas=document.querySelector('#dn-qr-code canvas'),qrImg=document.querySelector('#dn-qr-code img');
  const qrSrc=qrCanvas?qrCanvas.toDataURL('image/png'):(qrImg?.src||'');
  if(qrSrc)html=html.replace('<div class="dn-doc-qr-slot"></div>',`<div class="dn-doc-qr-slot"><img src="${qrSrc}" alt="Delivery QR" style="width:108px;height:108px"></div>`);
  const cust=dnCustomerProfile(so);
  // V270.4.8: "DN-2610-0003 - SNC Lavalin Arabia - PO2200005124" (no PO → no PO part; no Accepted / Standard ending)
  const baseName=[dnSafeFilePart(d.dnNo||'Delivery Note'),dnSafeFilePart(cust?.name),docPoFilePart(so.poNo)].filter(Boolean).join(' - ');
  const printTitle=baseName||'Delivery Note';
  const w=window.open('','_blank');if(!w){showToast('Please allow pop-ups to print the Delivery Note','warning');return}
  const safeTitle=escapeHtml(printTitle);
  w.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${safeTitle}</title><style>*{box-sizing:border-box}html,body{margin:0;background:#fff}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}</style>${window.BCPages?BCPages.head(BCPages.DN):''}</head><body>${html}<scr`+`ipt>(function(){var returned=false;var wantedTitle=${JSON.stringify(printTitle)};function keepTitle(){try{document.title=wantedTitle;}catch(e){}}function backToBizCore(){if(returned)return;returned=true;try{if(window.opener&&!window.opener.closed){window.opener.focus();}}catch(e){}setTimeout(function(){try{window.close();}catch(e){}},80);}window.addEventListener('beforeprint',keepTitle);window.addEventListener('afterprint',backToBizCore);window.onload=function(){keepTitle();requestAnimationFrame(function(){requestAnimationFrame(function(){keepTitle();setTimeout(function(){keepTitle();window.print();},180);});});};})();</scr`+`ipt></body></html>`);w.document.close();
}

/* ── Create Invoice / Partial Invoicing (V229) ── */
/** V260: the Sales Order ROW an item belongs to. DN items carry the quotation index in origIdx, which
 *  differs from the SO row when an SO contains only some quotation lines — so link by stable line ID,
 *  then by SO row, and only then by origIdx (for invoices created before V260, origIdx held the SO row). */
function soRowOfItem(so,it,kind){
  const items=so.items||[];
  if(it&&it.soLineId){const r=items.findIndex(x=>x.lineId===it.soLineId);if(r>=0)return r;}
  if(it&&it.soIdx!==undefined&&it.soIdx!==null&&items[Number(it.soIdx)])return Number(it.soIdx);
  if(kind==='dn'&&it&&it.origIdx!==undefined&&it.origIdx!==null){const r=items.findIndex((x,i)=>(x.origIdx!==undefined&&x.origIdx!==null?Number(x.origIdx):i)===Number(it.origIdx));if(r>=0)return r;}
  if(it&&it.origIdx!==undefined&&it.origIdx!==null)return Number(it.origIdx);
  return null;
}
/** True while some accepted quantity on this SO has not been invoiced yet. */
function soHasInvoiceableQty(so){return invoiceAvailableLines(so).some(x=>x.availableQty>0.001);}
function invoiceAcceptedQtyMap(so){
  const map={};
  (so.deliveries||[]).forEach(d=>{if(!d.customerConfirmed||d.voided)return;(d.items||[]).forEach(it=>{const idx=soRowOfItem(so,it,'dn');if(idx==null)return;map[idx]=roundQty((map[idx]||0)+deliveryAcceptedQty(d,it));});});
  return map;
}
function invoicePreviouslyInvoicedQtyMap(so){
  const map={};
  (so.invoices||[]).forEach(inv=>{
    if(inv&&inv.type==='advance')return; // V264: an advance bills money, not quantities
    if(Array.isArray(inv.items)&&inv.items.length){inv.items.forEach(it=>{const idx=soRowOfItem(so,it,'invoice');if(idx==null)return;map[idx]=roundQty((map[idx]||0)+(Number(it.qty)||0));});}
    else { // Backward compatibility: invoices created before partial invoicing represented the full SO.
      (so.items||[]).forEach((it,i)=>{map[i]=roundQty((map[i]||0)+(Number(it.qty)||0));});
    }
  });
  return map;
}
function invoiceAvailableLines(so){
  const accepted=invoiceAcceptedQtyMap(so), invoiced=invoicePreviouslyInvoicedQtyMap(so);
  return (so.items||[]).map((it,i)=>{const ordered=Number(it.qty)||0,a=Math.min(ordered,accepted[i]||0),iv=Math.min(ordered,invoiced[i]||0),available=roundQtyForUom(Math.max(0,a-iv),it.uom);return {...it,origIdx:i,soIdx:i,soLineId:it.lineId||'',acceptedQty:a,invoicedQty:iv,availableQty:available,invoiceQty:available};});
}
function invoiceLineVatRate(so,it){const r=Number(it.vatRate);return Number.isFinite(r)?r:Number(so.vatRate||0.15);}
function recalcInvoiceSummary(){
  const modal=document.getElementById('so-invoice-modal'),so=salesOrders.find(x=>x.id===modal?._soId);if(!so)return;
  let sub=0,vat=0,hasQty=false;
  (modal._invoiceLines||[]).forEach((it,i)=>{let q=roundQtyForUom(document.getElementById('inv-qty-'+i)?.value,it.uom);q=Math.max(0,Math.min(it.availableQty,q));const el=document.getElementById('inv-qty-'+i);if(el&&Number(el.value)!==q)el.value=q||0;const line=q*(Number(it.up)||0);sub+=line;vat+=line*invoiceLineVatRate(so,it);hasQty=hasQty||q>0;const amt=document.getElementById('inv-line-amount-'+i);if(amt)amt.textContent=documentMoney('customerInvoice','lineAmount',line);});
  sub=Math.round(sub*100)/100;vat=Math.round(vat*100)/100;const total=Math.round((sub+vat)*100)/100;
  document.getElementById('inv-sum-sub').textContent=documentMoney('customerInvoice','summary',sub);document.getElementById('inv-sum-vat').textContent=documentMoney('customerInvoice','summary',vat);document.getElementById('inv-sum-vat-label').textContent='VAT ('+Math.round((so.vatRate||0.15)*100)+'%)';document.getElementById('inv-sum-total').textContent=documentMoney('customerInvoice','grandTotal',total);
  const btn=document.getElementById('inv-create-btn');if(btn)btn.disabled=!hasQty;modal._invoiceTotals={subtotal:sub,vat,total};
}
function invoiceAllAvailable(){const m=document.getElementById('so-invoice-modal');(m._invoiceLines||[]).forEach((it,i)=>{const e=document.getElementById('inv-qty-'+i);if(e)e.value=it.availableQty;});recalcInvoiceSummary();}
function clearInvoiceQty(){const m=document.getElementById('so-invoice-modal');(m._invoiceLines||[]).forEach((it,i)=>{const e=document.getElementById('inv-qty-'+i);if(e)e.value=0;});recalcInvoiceSummary();}
function openCreateInvoice(soId, opts) {
  // V264: independent invoices (delivery / order / advance) use the new screen
  if(typeof invoiceModeRoute==='function'){const routed=invoiceModeRoute(soId, opts);if(routed!=='legacy')return routed;}
  const so=salesOrders.find(x=>x.id===soId);if(!so)return;currentSOId=soId;
  const lines=invoiceAvailableLines(so),availableLines=lines.filter(x=>x.availableQty>0.001);
  const today=bcLocalISO(),dueDate=new Date();dueDate.setDate(dueDate.getDate()+14);
  document.getElementById('inv-modal-title').textContent='Create Invoice — '+so.soNo;document.getElementById('inv-date').value=today;document.getElementById('inv-zoho').value='';document.getElementById('inv-due').value=bcLocalISO(dueDate);document.getElementById('inv-notes').value='';
  const body=document.getElementById('inv-items-list');body.innerHTML=availableLines.map((it,i)=>`<tr><td>${i+1}</td><td class="inv-item-description">${escapeHtml(it.desc||'—')}</td><td>${formatQuantity(it.acceptedQty)}</td><td>${formatQuantity(it.invoicedQty)}</td><td class="inv-available">${formatQuantity(it.availableQty)}</td><td>${escapeHtml(it.uom||'—')}</td><td>${documentMoney('customerInvoice','unitPrice',Number(it.up)||0)}</td><td><input class="inv-qty-input bc-spin" id="inv-qty-${i}" type="number" min="0" max="${it.availableQty}" step="${qtyStep(it.uom)}" value="${it.availableQty}" oninput="recalcInvoiceSummary()"></td><td class="inv-line-amount" id="inv-line-amount-${i}">—</td></tr>`).join('');
  document.getElementById('inv-empty-note').hidden=availableLines.length>0;document.querySelector('#so-invoice-modal .inv-items-table-wrap').style.display=availableLines.length?'block':'none';
  const modal=document.getElementById('so-invoice-modal');modal._soId=soId;modal._invoiceLines=availableLines;modal._invoiceTotals={subtotal:0,vat:0,total:0};openModalWithSize('so-invoice-modal');recalcInvoiceSummary();
}
async function saveInvoice() {
  const modal=document.getElementById('so-invoice-modal'),soId=modal._soId,so=salesOrders.find(x=>x.id===soId);if(!so)return;
  const date=document.getElementById('inv-date').value;if(!date){showToast('Please enter invoice date','error');return;}
  const items=[];(modal._invoiceLines||[]).forEach((it,i)=>{let qty=roundQtyForUom(document.getElementById('inv-qty-'+i)?.value,it.uom);qty=Math.max(0,Math.min(it.availableQty,qty));if(qty>0){const up=Number(it.up)||0,subtotal=Math.round(qty*up*100)/100,vatRate=invoiceLineVatRate(so,it),vat=Math.round(subtotal*vatRate*100)/100;items.push({origIdx:it.origIdx,soIdx:it.soIdx,soLineId:it.soLineId||'',desc:it.desc||'',uom:it.uom||'',qty,up,vatRate,subtotal,vat,total:Math.round((subtotal+vat)*100)/100});}});
  if(!items.length){showToast('Enter at least one invoice quantity','error');return;}
  // Recheck availability at save time to protect against duplicate/parallel invoicing.
  const latest=invoiceAvailableLines(so);for(const row of items){const avail=latest.find(x=>x.origIdx===row.origIdx)?.availableQty||0;if(row.qty>avail+0.001){showToast('Available quantity changed. Please reopen the invoice screen and try again.','error');return;}}
  const subtotal=Math.round(items.reduce((s,x)=>s+x.subtotal,0)*100)/100,vat=Math.round(items.reduce((s,x)=>s+x.vat,0)*100)/100,total=Math.round((subtotal+vat)*100)/100;
  const invNumber=await allocateDocumentNumber('customerInvoice',new Date(date+'T00:00:00'));
  const inv={invNo:invNumber,zohoNo:document.getElementById('inv-zoho').value.trim(),date,dueDate:document.getElementById('inv-due').value,notes:document.getElementById('inv-notes').value.trim(),items,subtotal,vat,total,isPartial:items.some(x=>(latest.find(y=>y.origIdx===x.origIdx)?.availableQty||0)>x.qty+0.001)||latest.some(x=>x.availableQty>0.001&&!items.some(y=>y.origIdx===x.origIdx)),created:new Date().toISOString()};
  so.invoices=so.invoices||[];so.invoices.push(inv);
  const invSaved=await saveSalesOrders({onlyIds:[so.id]});
  if(invSaved===false){so.invoices=so.invoices.filter(x=>x!==inv);if(dnIndependentMode()){const r=rawSalesOrders.find(x=>x.id===so.id);if(r&&Array.isArray(r.invoices))r.invoices=r.invoices.filter(x=>x.invNo!==inv.invNo);}showValidationDialog('Invoice Not Saved',salesOrderSaveFailureMessage(),'','');return;}
  closeModal('so-invoice-modal');showToast('Invoice '+inv.invNo+' created','success');renderSOPage();viewSO(soId);
}

/* ── Record Payment ── */
function openRecordPayment(soId) {
  const so = salesOrders.find(x=>x.id===soId); if (!so) return;
  currentSOId = soId;
  const totalPaid = (so.payments||[]).reduce((s,p)=>s+(parseFloat(p.amount)||0),0);
  const outstanding = so.total - totalPaid;
  document.getElementById('pay-modal-title').textContent = 'Record Payment — ' + so.soNo;
  document.getElementById('pay-outstanding-info').innerHTML =
    ((typeof invIndependentMode==='function'&&invIndependentMode()&&typeof soBilledTotal==='function')?`<strong>Invoiced so far (net):</strong> ${fmt(soBilledTotal(so))} &nbsp;·&nbsp; `:'')+`<strong>Order total:</strong> ${fmt(so.total)} &nbsp;·&nbsp; <strong>Paid so far:</strong> ${fmt(totalPaid)} &nbsp;·&nbsp; <strong>Outstanding:</strong> <span style="color:var(--red);font-weight:700">${fmt(outstanding)}</span>`;
  document.getElementById('pay-date').value = bcLocalISO();
  document.getElementById('pay-amount').value = outstanding.toFixed(2);
  document.getElementById('pay-method').value = 'Bank transfer';
  document.getElementById('pay-ref').value = '';
  document.getElementById('pay-remarks').value = '';
  document.getElementById('so-payment-modal')._soId = soId;
  document.getElementById('so-payment-modal')._outstanding = outstanding;
  updatePaymentBalance();
  openModalWithSize('so-payment-modal');
}

function updatePaymentBalance() {
  const modal = document.getElementById('so-payment-modal');
  const outstanding = modal._outstanding||0;
  const amount = parseFloat(document.getElementById('pay-amount')?.value)||0;
  const remaining = outstanding - amount;
  const info = document.getElementById('pay-balance-info');
  if (info) {
    if (remaining < -0.01) {
      info.innerHTML = `<span style="color:var(--red)">⚠ Amount exceeds outstanding by ${fmt(Math.abs(remaining))}</span>`;
    } else if (remaining < 0.01) {
      info.innerHTML = `<span style="color:var(--green)">✓ Full payment — order will be marked as Paid</span>`;
    } else {
      info.innerHTML = `Remaining after this payment: <strong style="color:var(--orange-txt)">${fmt(remaining)}</strong> — order will be marked as Partially Paid`;
    }
  }
}

async function savePayment() {
  const modal = document.getElementById('so-payment-modal');
  const soId = modal._soId;
  const so = salesOrders.find(x=>x.id===soId); if (!so) return;
  const date = document.getElementById('pay-date').value;
  const amount = parseFloat(document.getElementById('pay-amount').value)||0;
  if (!date) { showToast('Please enter payment date','error'); return; }
  if (amount <= 0) { showToast('Please enter a valid payment amount','error'); return; }

  const payment = {
    id:      'PAY-' + Date.now(),
    date,
    amount,
    method:  document.getElementById('pay-method').value,
    ref:     document.getElementById('pay-ref').value.trim(),
    remarks: document.getElementById('pay-remarks').value.trim(),
    created: new Date().toISOString(),
  };
  so.payments.push(payment);
  const paySaved = await saveSalesOrders({ onlyIds: [so.id] });
  if (paySaved === false) {
    so.payments = so.payments.filter(x => x !== payment);
    if (dnIndependentMode()) { const r = rawSalesOrders.find(x => x.id === so.id); if (r && Array.isArray(r.payments)) r.payments = r.payments.filter(x => x.id !== payment.id); }
    showValidationDialog('Payment Not Saved', salesOrderSaveFailureMessage(), '', '');
    return;
  }
  closeModal('so-payment-modal');
  const newStatus = getSOStatus(so);
  showToast('Payment recorded — Order is now ' + newStatus, 'success');
  renderSOPage();
  viewSO(soId);
}

