/* ═══════════════════════════════════════════════════════════════════
   V265 — Standard date filter (js/ui-standard.js, design "A") wired to every register.
   One component, one set of presets with one meaning (see BCDateFilter.range); each register keeps its own
   filter state. The previous per-screen helpers stay callable and now drive the standard component.
═══════════════════════════════════════════════════════════════════ */
(function wireStandardDateFilters(){
  const D = window.BCDateFilter; if (!D) { console.error('[BizCore] ui-standard.js not loaded — date filters unavailable'); return; }
  const norm = st => st.preset === 'all' ? { preset:'all', from:'', to:'' } : { preset:st.preset, from:st.from||'', to:st.to||'' };
  // RFQs
  rfqDateRangeForPreset = preset => D.range(preset);
  updateRFQDateFilterUI = () => D.set('rfq', rfqDateFilter);
  closeRFQDateMenu = () => D.close('rfq');
  toggleRFQDateMenu = e => { e?.stopPropagation(); D.open('rfq'); };
  D.register('rfq', st => { rfqDateFilter = norm(st); rfqPage = 1; renderRFQPage(); });
  // Pricing
  pricingDateRangeForPreset = preset => D.range(preset);
  updatePricingDateFilterUI = () => D.set('pricing', pricingDateFilter);
  closePricingDateMenu = () => D.close('pricing');
  togglePricingDateMenu = e => { e?.stopPropagation(); D.open('pricing'); };
  D.register('pricing', st => { pricingDateFilter = norm(st); pricingDocPage = 1; renderPricingDocuments(); });
  // Quotations (the register reads the hidden From / To inputs)
  const qSet = st => { const f = document.getElementById('filter-date-from'), t = document.getElementById('filter-date-to'); if (f) f.value = st.from || ''; if (t) t.value = st.to || ''; quotationDatePreset = st.preset; };
  D.register('quotation', st => { qSet(norm(st)); currentPage = 1; renderTable(); });
  setQuotationDatePreset = preset => D.choose('quotation', { preset });
  updateQuotationDateFilterUI = (label, preset) => { quotationDatePreset = preset || 'custom'; D.set('quotation', { preset: quotationDatePreset, from: document.getElementById('filter-date-from')?.value || '', to: document.getElementById('filter-date-to')?.value || '' }); };
  closeQuotationDateMenu = () => D.close('quotation');
  toggleQuotationDateMenu = e => { e?.stopPropagation(); D.open('quotation'); };
  clearQuotationDateFilter = () => D.choose('quotation', { preset:'all' });
  // Sales Orders
  const soSet = st => { soDateFilter = { mode: st.preset, from: st.from || null, to: st.to || null }; const f = document.getElementById('so-d-from'), t = document.getElementById('so-d-to'); if (f) f.value = st.from || ''; if (t) t.value = st.to || ''; };
  D.register('so', st => { soSet(norm(st)); soPage = 1; renderSOPage(); });
  filterSODate = mode => D.choose('so', { preset: mode || 'all' });
  clearSODateFilter = () => D.choose('so', { preset:'all' });
  const _clearAllSO = clearAllSOFilters;
  clearAllSOFilters = function(){ D.set('so', { preset:'all' }); return _clearAllSO.apply(this, arguments); };
  // Delivery Notes
  D.register('dn', st => { const n = norm(st); dnDateFilter = { mode: n.preset, from: n.from || null, to: n.to || null }; renderDNPage(); });
  filterDNDate = mode => D.choose('dn', { preset: mode || 'all' });
  const _clearAllDN = clearAllDNFilters;
  clearAllDNFilters = function(){ D.set('dn', { preset:'all' }); return _clearAllDN.apply(this, arguments); };
  // Invoices (state read by renderInvoiceRegister)
  D.register('invreg', () => { if (typeof renderInvoiceRegister === 'function') renderInvoiceRegister(); });
})();

/* ══════════════════════════════════════════════════
   V268.51 — drop-down lists float over the window and fit the screen
   (opens upwards when there is more room above; scroll inside the list, never the window).
   Older search lists (.cust-dropdown), the New Receipt customer picker and the quotation product list.
══════════════════════════════════════════════════ */
function bcFitList(list, anchor, minWidth){
  if(!list||!anchor) return;
  const r=anchor.getBoundingClientRect(), vw=window.innerWidth, vh=window.innerHeight;
  if(!r.width&&!r.height) return;
  // V268.61 (mockup V6_1): as wide as the field and kept inside the open window (above the footer), upwards when there is more room above
  const win=anchor.closest('.modal'), body=win&&(win.querySelector('.modal-body')||win), b=body?body.getBoundingClientRect():null;
  const lo=b?Math.min(vh,b.bottom):vh, hi=b?Math.max(0,b.top):0;
  const w=Math.min(vw-16,Math.max(r.width,minWidth||0)), below=lo-r.bottom-8, above=r.top-hi-8, up=below<160&&above>below;
  Object.assign(list.style,{position:'fixed',left:Math.max(8,Math.min(r.left,vw-w-8))+'px',right:'auto',width:w+'px',zIndex:'100000',margin:'0',
    top:up?'auto':(r.bottom+3)+'px',bottom:up?(vh-r.top+3)+'px':'auto',maxHeight:Math.max(120,Math.min(380,(up?above:below)))+'px',overflowY:'auto'});
}
function bcUnfitList(list){ if(!list) return; ['position','left','right','width','zIndex','margin','top','bottom','maxHeight','overflowY'].forEach(k=>list.style[k]=''); }
function bcListAnchor(list){
  if(list.classList.contains('cust-dropdown')) return list.parentElement.querySelector('input')||list.parentElement;
  if(list.id==='rn-cust-list'){ const s=document.getElementById('rn-pick-search'); return s&&!s.hidden?s:document.getElementById('rn-chosen'); }
  return null;
}
function bcListOpen(list){ return list.classList.contains('cust-dropdown')?list.classList.contains('open'):!list.hidden; }
function bcRefitLists(){
  document.querySelectorAll('.cust-dropdown.open, #rn-cust-list:not([hidden])').forEach(l=>bcFitList(l,bcListAnchor(l)));
  const pd=document.getElementById('prod-search-dd'); if(pd&&pd.style.display==='block'&&pd._anchor) bcFitList(pd,pd._anchor,360);
}
(function(){
  if(window.__bcListObserver) return;
  window.__bcListObserver=new MutationObserver(muts=>{
    muts.forEach(m=>{ const t=m.target; if(!(t instanceof HTMLElement)) return;
      if(!(t.classList.contains('cust-dropdown')||t.id==='rn-cust-list')) return;
      if(bcListOpen(t)) bcFitList(t,bcListAnchor(t)); else bcUnfitList(t); });
  });
  window.__bcListObserver.observe(document.body,{subtree:true,attributes:true,attributeFilter:['class','hidden']});
  window.addEventListener('resize',bcRefitLists);
  document.addEventListener('scroll',e=>{ if(e.target&&e.target.closest&&e.target.closest('.cust-dropdown,#rn-cust-list,#prod-search-dd')) return; bcRefitLists(); },true);
})();

/* ══════════════════════════════════════════════════════════════════════════════════════════
   V269.1 — DATA PLAN STEP 2a: only open and recent sales records are loaded (see index.html BCWin)
   Here: the "still open" mark on Sales Orders, older records on request (date filters, number search,
   Dashboard "All time", Reports, backup) and the server check before a master record is deleted.
   ══════════════════════════════════════════════════════════════════════════════════════════ */
const BC_REG_COLS = { rfq: ['rfqs'], pricing: ['rfqs'], quotation: ['quotations'], so: ['salesOrders'], dn: ['deliveryNotes'], invreg: ['customerInvoices', 'creditNotes'], rctreg: ['customerReceipts'] };
const BC_SEARCH_COLS = { 'rfq-search': ['rfqs'], 'pricing-doc-search': ['rfqs'], 'search-input': ['quotations'], 'so-search': ['salesOrders'], 'dn-search': ['deliveryNotes'], 'dl-search': ['deliveryNotes'], 'invreg-q': ['customerInvoices', 'creditNotes'], 'rctreg-q': ['customerReceipts'] };
function bcWinOn(){ return !!(window.BCWin && window.FB); }
/** Reads older records of these collections (from `from`, '' = all) when they aren't here yet, then runs `then`. */
async function bcEnsureOlder(cols, from, then){
  if (!bcWinOn()) { if (then) then(); return 0; }
  const need = cols.filter(c => window.BCWin.started(c) && !window.BCWin.hasOlder(c, from || ''));
  if (!need.length) { if (then) then(); return 0; }
  const cfg = await window.BCWin.config();
  if (from && from >= cfg.cutoff) { if (then) then(); return 0; }
  const t = setTimeout(() => showToast('Loading older records…', 'info'), 300);
  let n = 0;
  try { n = await window.BCWin.loadOlder(need, from || ''); }
  catch (e) { showToast(navigator.onLine === false ? 'You are offline. Older records can’t be read now.' : 'Older records could not be loaded. Please try again.', 'error'); }
  finally { clearTimeout(t); }
  if (then) then();
  return n;
}
/* registers: choosing "All Dates" or a date before the cut-off reads the older records first (ui-standard.js calls this) */
window.bcDateFilterBeforeChoose = function(key, st){
  const cols = BC_REG_COLS[key]; if (!cols || !bcWinOn()) return null;
  const from = st.preset === 'all' ? '' : (st.from || '');
  if (st.preset !== 'all' && !from) return null;
  return bcEnsureOlder(cols, from);
};
/* register search: Enter looks for that number in older records too */
document.addEventListener('keydown', async e => {
  if (e.key !== 'Enter' || !e.target || !BC_SEARCH_COLS[e.target.id] || !bcWinOn()) return;
  const text = String(e.target.value || '').trim(); if (text.length < 3 || !/\d/.test(text)) return;
  let n = 0;
  try { for (const c of BC_SEARCH_COLS[e.target.id]) if (window.BCWin.started(c)) n += await window.BCWin.findNumber(c, text); } catch (err) { return; }
  if (n) showToast(n === 1 ? 'Found 1 older record' : 'Found ' + n + ' older records', 'success');
  e.target.dispatchEvent(new Event('input', { bubbles: true }));
}, true);
/** The note under the date filter popups / on Reports: what is loaded. */
async function bcWindowNoteText(){
  if (!bcWinOn()) return '';
  const c = await window.BCWin.config();
  return 'Loaded: open records and everything since ' + fmtDate(c.cutoff) + '. Choose “All Dates” or an earlier date to read older records.';
}
window.bcWindowNoteText = bcWindowNoteText;

/* ── Sales Orders: isOpen (true until fully delivered, fully invoiced and every invoice settled) ── */
function soIsOpenNow(so){
  if (!so) return true;
  const deliveries = (so.deliveries || []).filter(d => !d.voided);
  if (deliveries.some(d => !d.customerConfirmed)) return true;                 // out for delivery
  const ordered = (so.items || []).reduce((s, it) => s + (parseFloat(it.qty) || 0), 0);
  const accepted = deliveries.reduce((s, d) => s + (d.items || []).reduce((t, it) => t + deliveryAcceptedQty(d, it), 0), 0);
  if (accepted < ordered - 0.001) return true;                                  // not all accepted (same measure as getSOStatus)
  if (typeof invIndependentMode === 'function' && invIndependentMode() && typeof invoicesForSO === 'function') {
    const inv = invoicesForSO(so.id).filter(i => !/cancel/i.test(String(i.status || '')));
    if (!inv.length) return true;
    const gross = inv.reduce((s, i) => s + (Number(i.totals && i.totals.total) || 0), 0);
    if (gross < (Number(so.total) || 0) - 0.01) return true;                     // not fully invoiced
    if (typeof invoiceBalanceOf === 'function' && inv.some(i => invoiceBalanceOf(i) > 0.01)) return true;   // money still due
    return false;
  }
  return getSOStatus(so) !== 'Paid';
}
let _bcHealRunning = false;
const _bcHealRefused = new Set();   // V269.2.1: orders whose mark the rules refused — not tried again this session
/** V269.2.1: an old order that still has deliveries / invoices inside it (from before they got their own records)
 *  can't be changed in independent mode (the rules refuse it) — don't try to mark it. */
function bcHealBlocked(so){
  if (_bcHealRefused.has(String(so.id))) return true;
  try { const j = window.FB.fbSyncedJSON ? window.FB.fbSyncedJSON('salesOrders', so.id) : null; if (!j) return false;
    const d = JSON.parse(j); return (Array.isArray(d.deliveries) && d.deliveries.length > 0) || (Array.isArray(d.invoices) && d.invoices.length > 0);
  } catch (e) { return false; }
}
/** Keeps the isOpen mark of the loaded Sales Orders right (one small write when an order closes or reopens). */
async function bcHealOpenOrders(){
  if (_bcHealRunning || !bcWinOn() || !window.FB.fbMergeFields || !Array.isArray(salesOrders)) return 0;
  if (dnIndependentMode() && !dnCacheLoaded) return 0;
  if (typeof invIndependentMode === 'function' && invIndependentMode() && !(window.BCWin.started('customerInvoices') && window.BCWin.started('invoicePayments'))) return 0;
  _bcHealRunning = true; let n = 0;
  try {
    await window.BCWin.idle();
    for (const so of salesOrders.slice()) {
      if (!so || !so.id || String(so.id).startsWith('tmp')) continue;
      const open = soIsOpenNow(so);
      if (so.isOpen === open || bcHealBlocked(so)) continue;
      const ok = await window.FB.fbMergeFields('salesOrders', so.id, { isOpen: open });
      if (!ok) { _bcHealRefused.add(String(so.id)); continue; }
      {
        so.isOpen = open; n++;
        const raw = (typeof rawSalesOrders !== 'undefined' ? rawSalesOrders : []).find(x => x.id === so.id); if (raw) raw.isOpen = open;
      }
    }
  } catch (e) { console.warn('[BizCore] open-order marks not updated:', e.message); }
  finally { _bcHealRunning = false; }
  return n;
}
window.bcHealOpenOrders = bcHealOpenOrders;
(function(){ const go = () => { if (window.__bcDataReady) bcHealOpenOrders(); }; setTimeout(go, 8000); setInterval(go, 60000); })();

/* ── before a customer / product / supplier is deleted: is it used by a record that isn't loaded? ── */
async function bcOlderDependencies(type, records, onProgress){
  // V270.4.9: the same checks as before, but up to 30 records per question and all questions at the same time
  // (it was one question per record and document list, one after the other — about 300 for 50 customers)
  if (!bcWinOn() || !window.BCWin.anyWhere) return [];
  const W = window.BCWin, checks = [];
  const add = (col, field, op, valueOf, label) => checks.push({ col, field, op, valueOf, label });
  if (type === 'customers') {
    add('quotations', 'custId', '==', r => r.id, 'older quotations'); add('quotations', 'company', '==', r => r.company, 'older quotations');
    add('rfqs', 'custId', '==', r => r.id, 'older RFQs'); add('rfqs', 'company', '==', r => r.company, 'older RFQs');
    add('salesOrders', 'custId', '==', r => r.id, 'older sales orders'); add('salesOrders', 'customer', '==', r => r.company, 'older sales orders');
  } else if (type === 'products') {
    const C = window.BizCorePI && window.BizCorePI.core;
    const keyOf = r => C ? C.itemKeyOf({ productId: r.id }) : 'p_' + String(r.id).replace(/[^A-Za-z0-9_-]/g, '-');
    const codeOf = r => String(r.code || '').trim().toLowerCase();
    for (const [col, label] of [['quotations', 'older quotations'], ['rfqs', 'older RFQ/pricing documents'], ['salesOrders', 'older sales orders']]) {
      add(col, 'productIds', 'array-contains', r => r.id, label); add(col, 'productCodes', 'array-contains', codeOf, label);
    }
    add('purchaseInvoices', 'itemKeys', 'array-contains', keyOf, 'purchase invoices');   // V269.4: purchasing and stock — any age
    add('stockItems', 'itemKey', '==', keyOf, 'stock');
  } else if (type === 'suppliers') {
    add('rfqs', 'supplierIds', 'array-contains', r => r.id, 'older RFQ/pricing documents');
    add('purchaseInvoices', 'supplierId', '==', r => r.id, 'purchase invoices');
    add('supplierPayments', 'supplierId', '==', r => r.id, 'supplier payments');
  }
  const deps = new Map(records.map(r => [r, new Set()]));
  let done = 0; if (onProgress) onProgress(0, checks.length);
  await Promise.all(checks.map(async ch => {
    try {
      const used = W.usedValues ? await W.usedValues(ch.col, ch.field, ch.op, records.map(ch.valueOf))
        : new Set((await Promise.all(records.map(async r => { const v = ch.valueOf(r); return v != null && v !== '' && await W.anyWhere(ch.col, ch.field, ch.op, v) ? v : null; }))).filter(v => v != null));
      records.forEach(r => { const v = ch.valueOf(r); if (v != null && v !== '' && used.has(v)) deps.get(r).add(ch.label); });
    } catch (e) {
      const why = e && e.code === 'bc-no-permission' ? 'records your role can\'t see (ask an administrator to delete it)' : 'records that could not be checked (' + (navigator.onLine === false ? 'offline' : 'no connection') + ') — try again';
      records.forEach(r => deps.get(r).add(why));
    }
    done++; if (onProgress) onProgress(done, checks.length);
  }));
  return records.filter(r => deps.get(r).size).map(r => ({ record: r, dependencies: [...deps.get(r)] }));
}

/* ── Reports: a note and "Include older records" ── */
async function bcRenderAnalyticsWindowNote(){
  const page = document.getElementById('page-analytics'); if (!page || !bcWinOn()) return;
  let note = document.getElementById('an-window-note');
  if (!note) { note = document.createElement('div'); note.id = 'an-window-note'; note.className = 'bc-window-note'; page.insertBefore(note, page.firstChild); }
  const all = ['quotations', 'rfqs', 'salesOrders'].every(c => !window.BCWin.started(c) || window.BCWin.hasOlder(c, ''));
  const c = await window.BCWin.config();
  note.innerHTML = all ? '<i class="ti ti-database"></i><span>All records are included.</span>'
    : '<i class="ti ti-database"></i><span>Figures include open records and everything since ' + fmtDate(c.cutoff) + '.</span> <button type="button" class="btn btn-secondary btn-sm" onclick="bcEnsureOlder([\'quotations\',\'rfqs\',\'salesOrders\'],\'\',renderAnalytics)">Include older records</button>';
}


/* ── V270.4.9 — master record forms: code, same / similar name notice, VAT No. block, rename (js/master-ui.js) ── */
(function bcBindMasterForms(){
  if(!window.BCMasterUI) return;
  const same=(a,b)=>String(a||'').trim().toLowerCase()===String(b||'').trim().toLowerCase();
  const usageCustomer=c=>{ if(!c) return 0; const mine=x=>(x.custId&&x.custId===c.id)||(x.customerId&&x.customerId===c.id)||(!x.custId&&!x.customerId&&same(x.company||x.customer,c.company));
    return quotations.filter(mine).length+rfqs.filter(r=>(r.custId&&r.custId===c.id)||(!r.custId&&same(r.customer||r.company,c.company))).length+salesOrders.filter(mine).length+(typeof invoicesCache!=='undefined'?invoicesCache.filter(mine).length:0); };
  const usageSupplier=s=>{ if(!s) return 0; const pis=(window.BizCorePI&&window.BizCorePI.invoices)||(typeof piInvoices==='function'?piInvoices():[]);
    return (pis||[]).filter(x=>(x.supplierId&&x.supplierId===s.id)||same(x.supplierName,s.company)).length+rfqs.filter(r=>JSON.stringify(r.pricing||r.items||'').includes('"'+s.id+'"')).length; };
  const usageProduct=p=>{ if(!p) return 0; const has=list=>(list||[]).some(it=>it&&((it.prodId&&it.prodId===p.id)||(it.productId&&it.productId===p.id)));
    return quotations.filter(q=>has(q.items)).length+salesOrders.filter(o=>has(o.items)).length; };
  const reopen=(modal,fn)=>id=>{ try{clearDirty();}catch(_){} closeModal(modal); setTimeout(()=>fn(id),50); };
  BCMasterUI.bind({col:'customers',boxId:'cust-modal',titleSel:'#cust-modal-title',nameId:'cm-company',vatId:'cm-vat',nameField:'company',label:'customer',
    list:()=>customers,getId:()=>editingCustId,current:()=>editingCustId?customers.find(x=>x.id===editingCustId):null,open:reopen('cust-modal',openEditCustomer),
    meta:c=>[c.city,c.contact].filter(Boolean).join(' · '),usage:usageCustomer});
  BCMasterUI.bind({col:'suppliers',boxId:'sup-modal',titleSel:'#sup-modal-title',nameId:'sm-company',vatId:'sm-vat',nameField:'company',label:'supplier',
    list:()=>suppliers,getId:()=>editingSupId,current:()=>editingSupId?suppliers.find(x=>x.id===editingSupId):null,open:reopen('sup-modal',openEditSupplier),
    meta:s=>[s.city,s.contact].filter(Boolean).join(' · '),usage:usageSupplier});
  BCMasterUI.bind({col:'products',boxId:'prod-modal',titleSel:'#prod-modal-title',nameId:'pm-name',nameField:'name',label:'product',
    list:()=>products,getId:()=>editingProdId,current:()=>editingProdId?products.find(x=>x.id===editingProdId):null,open:reopen('prod-modal',openEditProduct),
    meta:p=>[p.brand,p.uom].filter(Boolean).join(' · '),usage:usageProduct});
  BCMasterUI.bind({col:'employees',boxId:'employee-form-panel',titleSel:'#employee-form-title',nameId:'emp-name',nameField:'name',label:'employee',
    list:()=>employees,getId:()=>editingEmployeeId,current:()=>editingEmployeeId?employees.find(x=>x.id===editingEmployeeId):null,open:id=>openEmployeeForm(id)});
})();
